# EXISTS
session.query(Employee).filter(
    Employee.dept_id.in_(
        session.query(Department.id).filter(Department.location == 'NYC')
    )
).all()

# NOT EXISTS
session.query(Employee).filter(
    ~Employee.dept_id.in_(
        session.query(Department.id).filter(Department.location == 'NYC')
    )
).all()

# Conditional aggregation
from sqlalchemy import func, case
session.query(
    Employee.dept_id,
    func.sum(case((Employee.status == 'active', 1), else_=0)).label('active_cnt'),
    func.sum(case((Employee.status == 'pending', 1), else_=0)).label('pending_cnt')
).group_by(Employee.dept_id).all()
